<?php

declare(strict_types=1);require_once __DIR__.'/../../includes/module-admin.php';$pdo=cmsAdminModuleBoot('analytics');$days=max(1,min(365,cmsInt($_GET['days']??30,30)));$from=(new DateTimeImmutable('today'))->modify('-'.($days-1).' days')->format('Y-m-d');$sum=$pdo->prepare('SELECT event_type,SUM(event_count) total FROM analytics_daily WHERE event_date>=:f GROUP BY event_type ORDER BY total DESC');$sum->execute([':f'=>$from]);$totals=[];foreach($sum->fetchAll() as $r)$totals[$r['event_type']]=(int)$r['total'];$top=$pdo->prepare('SELECT entity_type,entity_key,entity_id,SUM(event_count) total FROM analytics_daily WHERE event_date>=:f AND entity_type<>"" GROUP BY entity_type,entity_key,entity_id ORDER BY total DESC LIMIT 30');$top->execute([':f'=>$from]);$daily=$pdo->prepare('SELECT event_date,SUM(event_count) total FROM analytics_daily WHERE event_date>=:f GROUP BY event_date ORDER BY event_date DESC');$daily->execute([':f'=>$from]);cmsAdminHead('الإحصائيات');cmsAdminSidebar('analytics');cmsAdminTopbar('الإحصائيات');?>
<div class="content"><div class="toolbar"><div class="actions"><?php foreach([7,30,90,365] as $d):?><a class="btn <?=$days===$d?'primary':''?>" href="?days=<?=$d?>"><?=$d?> يوم</a><?php endforeach;?></div></div><section class="grid cards"><article class="card"><div class="muted">زيارات الصفحات</div><div class="metric"><?=intval($totals['page_view']??0)?></div></article><article class="card"><div class="muted">مشاهدات الأقسام</div><div class="metric"><?=intval($totals['section_view']??0)?></div></article><article class="card"><div class="muted">مشاهدات العناصر</div><div class="metric"><?=intval($totals['item_view']??0)?></div></article><article class="card"><div class="muted">Conversions</div><div class="metric"><?=intval(($totals['conversion']??0)+($totals['whatsapp_click']??0))?></div></article></section><div class="split" style="margin-top:18px"><section class="card"><h2>أعلى العناصر</h2><div class="table-wrap"><table class="table"><thead><tr><th>النوع</th><th>العنصر</th><th>المشاهدات</th></tr></thead><tbody><?php foreach($top->fetchAll() as $r):?><tr><td><?=cmsE($r['entity_type'])?></td><td><?=cmsE($r['entity_key']?:('#'.$r['entity_id']))?></td><td><?=$r['total']?></td></tr><?php endforeach;?></tbody></table></div></section><section class="card"><h2>حسب اليوم</h2><div class="table-wrap"><table class="table"><thead><tr><th>اليوم</th><th>الإجمالي</th></tr></thead><tbody><?php foreach($daily->fetchAll() as $r):?><tr><td><?=cmsE($r['event_date'])?></td><td><?=$r['total']?></td></tr><?php endforeach;?></tbody></table></div></section></div></div><?php cmsAdminEnd();
